/**
 * A member CLI's own subagents in Context Lens (member-cli-subagents M7),
 * replayed from logs the local-agent core REALLY wrote
 * (fixtures/local-agent-cli-subagents.json, generated by local-agent's
 * `tests/lens-contract.spec.ts` through `openCliSubagent`): a member log
 * whose round one runs a foreground `Agent` subagent and a three-way
 * `AgentSwarm`, and whose round two resumes the first subagent, plus every
 * grandchild log. Read through the real service and log lane: the member's
 * catalog rows open the grandchild views, and each view is placed by its
 * execution records (`cli-subagent` cause → the member's call and
 * execution), never by time. The existing look gains content only: one tab
 * per subagent after its caller, one timing lane, the caller's 「派出 X →」,
 * and the turn totals saying the subagents' part.
 */
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { Context } from '@deepseek-ai/cordis'
import SessionStore from '@deepseek-ai/dsh-session'
import { InspectorService } from '../src/service.ts'
import type { SessionLogHandle, SessionLogReader, SessionLogRow } from '../src/log-lane.ts'
import type { AgentScopeOverview } from '../src/types.ts'

interface Fixture {
  readonly childSessionId: string
  readonly rows: SessionLogRow[]
  readonly grandchildren: { key: string; sessionId: string; rows: SessionLogRow[] }[]
}

const fixture = JSON.parse(readFileSync(new URL('./fixtures/local-agent-cli-subagents.json', import.meta.url), 'utf8')) as Fixture
const member = fixture.childSessionId
const [explore, coder1, coder2, coder3] = fixture.grandchildren.map(grandchild => grandchild.sessionId) as [string, string, string, string]
const starts = fixture.rows.filter(row => row.type === 'local-agent/execution' && (row.data as { phase?: string }).phase === 'start')
const [first, second] = starts.map(row => ({ executionId: (row.data as { executionId: string }).executionId, at: row.time! })) as [{ executionId: string; at: number }, { executionId: string; at: number }]
const endOf = (executionId: string): number => fixture.rows.find(row => row.type === 'local-agent/execution' && (row.data as { executionId?: string; phase?: string }).executionId === executionId && (row.data as { phase?: string }).phase === 'end')!.time!

/** The room the member answered: two human rounds, each run naming its member execution. */
const ROOM = 'room-session'
const roomRows: SessionLogRow[] = [
  { type: 'room/member-added', seq: 1, time: 1, data: { id: 'm-ada', name: 'ada' } },
  { type: 'room/dispatch', seq: 20, time: first.at - 5, data: { origin: 'human', text: '找穿模点，再出三段字幕', targets: ['ada'], messageId: 'u-20' } },
  { type: 'subagent/catalog', seq: 21, time: first.at - 4, data: { childId: member, mode: 'session', label: 'ada' } },
  { type: 'room/run-state', seq: 22, time: endOf(first.executionId), data: { runId: '20:m-ada', member: 'ada', state: 'done', startedAt: first.at, elapsedMs: endOf(first.executionId) - first.at, childSessionId: member, executionId: first.executionId } },
  { type: 'room/dispatch', seq: 30, time: second.at - 5, data: { origin: 'human', text: '再看一处', targets: ['ada'], messageId: 'u-30' } },
  { type: 'room/run-state', seq: 31, time: endOf(second.executionId), data: { runId: '30:m-ada', member: 'ada', state: 'done', startedAt: second.at, elapsedMs: endOf(second.executionId) - second.at, childSessionId: member, executionId: second.executionId } },
]

/** A `sessionPersistence`-shaped reader over the room, the member and its grandchildren. */
class LogReader implements SessionLogReader {
  readonly logs = new Map<string, SessionLogRow[]>([[ROOM, roomRows], [member, fixture.rows], ...fixture.grandchildren.map(grandchild => [grandchild.sessionId, grandchild.rows] as [string, SessionLogRow[]])])
  readonly opens: string[] = []
  async open(id: string): Promise<SessionLogHandle> {
    this.opens.push(id)
    const rows = this.logs.get(id)
    if (rows === undefined) {
      const notFound = new Error(`session "${id}" not found`)
      notFound.name = 'SessionPersistenceNotFoundError'
      throw notFound
    }
    return { read: (offset = 0) => Promise.resolve({ events: rows.slice(offset) }), close: () => Promise.resolve() }
  }
}

async function mount(): Promise<{ service: InspectorService; reader: LogReader }> {
  const ctx = new Context()
  await ctx.plugin(SessionStore)
  const reader = new LogReader()
  return { service: new InspectorService(ctx, {}, { persistence: reader, logger: { warn: () => {} } }), reader }
}

const tabs = (scopes: readonly AgentScopeOverview[]) => scopes.map(scope => [scope.scopeId, scope.label ?? scope.kind, scope.requests.length, scope.status])
const inputs = (scope: AgentScopeOverview | undefined) => scope?.requests.map(request => request.usage?.inputTokens)

async function roomRounds(service: InspectorService) {
  const list = await service.listTurns(ROOM)
  const one = list.turns.find(turn => turn.room?.messageId === 'u-20')!
  const two = list.turns.find(turn => turn.room?.messageId === 'u-30')!
  return { list, one, two }
}

describe('a member CLI\'s own subagents in Context Lens (fixture from the core\'s grandchild writer)', () => {
  it('room view: each subagent is one more tab right after its member, holding only what its call ran', async () => {
    const { service } = await mount()
    const { one, two } = await roomRounds(service)
    const round = (await service.getTurn(ROOM, one.turnSeq))!
    expect(tabs(round.scopes)).toEqual([
      [member, 'ada', 3, 'ok'],
      [explore, 'ada › explore', 2, 'ok'],
      [coder1, 'ada › coder 1', 1, 'ok'],
      [coder2, 'ada › coder 2', 1, 'ok'],
      // The third swarm subagent never finished: stopped, not failed.
      [coder3, 'ada › coder 3', 1, 'cancelled'],
    ])
    expect(inputs(round.scopes[1])).toEqual([800, 900])
    expect(round.scopes.slice(2).map(scope => scope.cliSubagent?.group)).toEqual([{ index: 0, size: 3 }, { index: 1, size: 3 }, { index: 2, size: 3 }])
    // Paired by callId: the member request whose call started it (「由 ada #1 派出」), and that request's 「派出 X →」.
    const [call, swarm] = round.scopes[0]!.requests
    expect(round.scopes[1]).toMatchObject({ delegatedBy: { turnSeq: one.turnSeq, scopeId: member, seq: call!.seq }, cliSubagent: { parentScopeId: member, parentName: 'ada', name: 'explore', callId: 'call-explore' } })
    expect(round.scopes.slice(2).map(scope => scope.delegatedBy?.seq)).toEqual([swarm!.seq, swarm!.seq, swarm!.seq])
    expect(round.scopes[0]!.requests.map(request => request.spawns?.map(spawn => spawn.name))).toEqual([['explore'], ['coder 1', 'coder 2', 'coder 3'], undefined])
    expect(round.scopes[1]!.requests.every(request => request.spawnedFrom === member)).toBe(true)
    expect(round.scopes[1]!.execution).toMatchObject({ cause: 'cli-subagent', outcome: 'done', unrecorded: ['internal-calls'] })
    // Round two: the resumed subagent, with that call's request only.
    const later = (await service.getTurn(ROOM, two.turnSeq))!
    expect(tabs(later.scopes)).toEqual([[member, 'ada', 2, 'ok'], [explore, 'ada › explore', 1, 'ok']])
    expect(later.scopes[1]).toMatchObject({ cliSubagent: { callId: 'call-resume', resumed: true }, execution: { cause: 'cli-subagent', resumed: true } })
    expect(inputs(later.scopes[1])).toEqual([1000])
  })

  it('room totals: the subagents\' requests count once, and their part is said', async () => {
    const { service } = await mount()
    const { one, two } = await roomRounds(service)
    expect(one).toMatchObject({ requestCount: 8, totalInputTokens: 2000 + 2100 + 2200 + 800 + 900 + 500 + 510 + 520, totalOutputTokens: 50 + 60 + 70 + 30 + 40 + 20 * 3,
      subagents: { requestCount: 5, inputTokens: 800 + 900 + 500 + 510 + 520, outputTokens: 30 + 40 + 20 * 3 } })
    expect(two).toMatchObject({ requestCount: 3, totalInputTokens: 2300 + 2400 + 1000, subagents: { requestCount: 1, inputTokens: 1000, outputTokens: 25 } })
  })

  it('timing: one lane per subagent beside its member\'s, on the shared clock; the member\'s call waits on it', async () => {
    const { service } = await mount()
    const { one } = await roomRounds(service)
    const timing = (await service.getTurnTiming(ROOM, one.turnSeq))!
    const lanesOf = (scopeId: string) => timing.lanes.filter(lane => lane.scopeId === scopeId)
    for (const scopeId of [member, explore, coder1, coder2, coder3]) expect(lanesOf(scopeId).length).toBeGreaterThan(0)
    // The member's Agent call is a tool execution whose callId the subagent view names.
    expect(lanesOf(member).some(lane => lane.kind === 'tool-exec' && lane.callId === 'call-explore')).toBe(true)
    // The subagent's own tool call is in its lane, not the member's.
    expect(lanesOf(explore).some(lane => lane.kind === 'tool-exec' && lane.tool === 'Grep')).toBe(true)
    expect(lanesOf(member).some(lane => lane.tool === 'Grep')).toBe(false)
  })

  it('member\'s own lens: the subagents are tabs of the member turn that called them, after 主对话; a resumed one in each turn', async () => {
    const { service } = await mount()
    const list = await service.listTurns(member)
    const real = list.turns.filter(turn => turn.hostTurn !== undefined)
    expect(real.map(turn => [turn.hostTurn, turn.requestCount, turn.subagents?.requestCount])).toEqual([[1, 8, 5], [2, 3, 1]])
    const one = (await service.getTurn(member, real[0]!.turnSeq))!
    expect(tabs(one.scopes)).toEqual([
      ['main', 'main', 3, 'ok'],
      [explore, 'explore', 2, 'ok'],
      [coder1, 'coder 1', 1, 'ok'],
      [coder2, 'coder 2', 1, 'ok'],
      [coder3, 'coder 3', 1, 'cancelled'],
    ])
    expect(one.scopes[1]).toMatchObject({ delegatedBy: { turnSeq: real[0]!.turnSeq, scopeId: 'main', seq: one.scopes[0]!.requests[0]!.seq }, cliSubagent: { parentScopeId: 'main', name: 'explore' } })
    expect(one.scopes[1]!.cliSubagent?.parentName).toBeUndefined()
    const two = (await service.getTurn(member, real[1]!.turnSeq))!
    expect(tabs(two.scopes)).toEqual([['main', 'main', 2, 'ok'], [explore, 'explore', 1, 'ok']])
    // The session map draws the subagents' requests with their caller's turn.
    const trend = await service.getSessionTrend(member)
    expect(trend.requests.filter(request => request.spawnedFrom === 'main').map(request => request.turnSeq)).toEqual([...Array(5).fill(real[0]!.turnSeq), real[1]!.turnSeq])
  })

  it('the room and the member\'s own lens read the same grandchild logs, each with its own rows', async () => {
    const { service, reader } = await mount()
    const { one } = await roomRounds(service)
    const list = await service.listTurns(member)
    const memberTurn = list.turns.find(turn => turn.hostTurn === 1)!
    expect((await service.getTurn(member, memberTurn.turnSeq))!.scopes.map(scope => scope.requests.length)).toEqual([3, 2, 1, 1, 1])
    expect((await service.getTurn(ROOM, one.turnSeq))!.scopes.map(scope => scope.requests.length)).toEqual([3, 2, 1, 1, 1])
    // A subagent's request opens with its full context from either view.
    const room = (await service.getTurn(ROOM, one.turnSeq))!
    const opened = await service.getRequest(ROOM, room.scopes[1]!.requests[0]!.seq)
    expect(opened).toMatchObject({ scopeId: explore })
    expect(reader.opens.filter(id => id === explore).length).toBeGreaterThanOrEqual(2)
  })

  it('without its execution records a catalogued child is not placed as a CLI subagent (no pairing by order or time)', async () => {
    const { service, reader } = await mount()
    // The same grandchild logs, their records cut: nothing names the member's call.
    for (const grandchild of fixture.grandchildren) reader.logs.set(grandchild.sessionId, grandchild.rows.filter(row => row.type !== 'local-agent/execution'))
    const { one } = await roomRounds(service)
    const round = (await service.getTurn(ROOM, one.turnSeq))!
    expect(tabs(round.scopes)).toEqual([[member, 'ada', 3, 'ok']])
    expect(one.subagents).toBeUndefined()
  })
})
